   /**
    * Remove the ith child node and shift the children[] array appropriately
    * @param i Index of child to remove
    * @return A reference to the removed node, or null if none was removed
    */
   public SimExprNode jjtRemoveChild (int i) {
      
      if (children==null || i >= children.length)
         return null;

      SimExprNode orphan = children[i];
      SimExprSimpleNode[] c = new SimExprSimpleNode[children.length - 1];
      if (i == 0)
          System.arraycopy(children, 1, c, 0, children.length - 1);
      else {
          System.arraycopy(children, 0, c, 0, i);
          if (i < (children.length - 1))
              System.arraycopy(children, i + 1, c, i, 
                               children.length - i - 1);
      }
      children = c;
      orphan.jjtSetParent(null);
      return orphan;
   }      

